package com.wikitagbankhighlighter;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.BiConsumer;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

public class WikiBucketClient
{
    private static final int PAGE_SIZE = 2000;
    private static final String CATEGORY_PREFIX = "Category:";
    private static final String WIKI_BUCKET_QUERY_FORMAT =
            "https://oldschool.runescape.wiki/api.php?action=bucket&query=%s&format=json";
    private static final String WIKI_SEARCH_URL_FORMAT =
            "https://oldschool.runescape.wiki/api.php?action=query&list=search&srnamespace=14&srlimit=1&format=json&formatversion=2&srsearch=%s";

    /**
     * Async: fetch item ids for a wiki category using OSRS Wiki bucket endpoint.
     *
     * callback.accept(ids, error)
     * - ids is never null (empty array on failure)
     * - error is null on success
     */
    public static void fetchCategoryItemIdsAsync(
            OkHttpClient http,
            String category,
            BiConsumer<int[], Throwable> callback
    )
    {
        final String normalized = normalizeForBucket(category);
        resolveCategoryNameAsync(http, normalized, (resolvedCategory, err) ->
        {
            if (err != null)
            {
                callback.accept(new int[0], err);
                return;
            }

            final String safe = escapeBucketString(resolvedCategory);
            final String baseQuery = String.format("bucket('item_id').select('item_id.id').where('%s%s')", CATEGORY_PREFIX, safe);
            fetchCategoryPageAsync(http, baseQuery, 0, new HashSet<>(1024), callback);
        });
    }

    public static void fetchCategoryItemIdsAsync(
            OkHttpClient http,
            List<String> categories,
            BiConsumer<int[], Throwable> callback
    )
    {
        List<String> normalized = normalizeCategories(categories);
        if (normalized.isEmpty())
        {
            callback.accept(new int[0], null);
            return;
        }

        if (normalized.size() == 1)
        {
            fetchCategoryItemIdsAsync(http, normalized.get(0), callback);
            return;
        }

        Set<Integer> merged = Collections.synchronizedSet(new HashSet<>(1024));
        AtomicInteger remaining = new AtomicInteger(normalized.size());
        AtomicReference<Throwable> firstError = new AtomicReference<>();

        for (String category : normalized)
        {
            fetchCategoryItemIdsAsync(http, category, (ids, err) ->
            {
                if (err != null)
                {
                    firstError.compareAndSet(null, err);
                }

                for (int id : ids)
                {
                    if (id > 0)
                    {
                        merged.add(id);
                    }
                }

                if (remaining.decrementAndGet() == 0)
                {
                    int[] out = merged.stream().mapToInt(i -> i).toArray();
                    callback.accept(out, firstError.get());
                }
            });
        }
    }

    private static void fetchCategoryPageAsync(
            OkHttpClient http,
            String baseQuery,
            int offset,
            Set<Integer> out,
            BiConsumer<int[], Throwable> callback
    )
    {
        String pagedQuery = String.format("%s.limit(%d).offset(%d).run()", baseQuery, PAGE_SIZE, offset);
        String url = String.format(WIKI_BUCKET_QUERY_FORMAT, urlEncode(pagedQuery));
        Request req = new Request.Builder().url(url).build();

        http.newCall(req).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
                callback.accept(new int[0], e);
            }

            @Override
            public void onResponse(Call call, Response resp) throws IOException
            {
                if (!resp.isSuccessful() || resp.body() == null)
                {
                    callback.accept(new int[0], new IOException("HTTP " + resp.code()));
                    return;
                }

                String json = resp.body().string();

                try
                {
                    JsonParser parser = new JsonParser();
                    JsonObject root = parser.parse(json).getAsJsonObject();
                    JsonArray bucket = root.has("bucket") && root.get("bucket").isJsonArray()
                            ? root.getAsJsonArray("bucket")
                            : null;

                    if (bucket == null || bucket.size() == 0)
                    {
                        callback.accept(out.stream().mapToInt(i -> i).toArray(), null);
                        return;
                    }

                    for (JsonElement el : bucket)
                    {
                        collectItemIds(el, out);
                    }

                    if (bucket.size() < PAGE_SIZE)
                    {
                        callback.accept(out.stream().mapToInt(i -> i).toArray(), null);
                        return;
                    }

                    fetchCategoryPageAsync(http, baseQuery, offset + PAGE_SIZE, out, callback);
                }
                catch (Throwable t)
                {
                    callback.accept(new int[0], t);
                }
            }
        });
    }

    private static void resolveCategoryNameAsync(
            OkHttpClient http,
            String category,
            BiConsumer<String, Throwable> callback
    )
    {
        if (category == null || category.isEmpty())
        {
            callback.accept("", null);
            return;
        }

        String query = String.format("\"%s\"", category);
        String url = String.format(WIKI_SEARCH_URL_FORMAT, urlEncode(query));
        Request req = new Request.Builder().url(url).build();

        http.newCall(req).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
                callback.accept(category, null);
            }

            @Override
            public void onResponse(Call call, Response resp) throws IOException
            {
                if (!resp.isSuccessful() || resp.body() == null)
                {
                    callback.accept(category, null);
                    return;
                }

                try
                {
                    String json = resp.body().string();
                    JsonParser parser = new JsonParser();
                    JsonObject root = parser.parse(json).getAsJsonObject();
                    JsonObject queryObject = root.has("query") && root.get("query").isJsonObject()
                            ? root.getAsJsonObject("query")
                            : null;
                    JsonArray search = queryObject != null && queryObject.has("search") && queryObject.get("search").isJsonArray()
                            ? queryObject.getAsJsonArray("search")
                            : null;

                    if (search == null || search.size() == 0)
                    {
                        callback.accept(category, null);
                        return;
                    }

                    JsonElement first = search.get(0);
                    if (!first.isJsonObject())
                    {
                        callback.accept(category, null);
                        return;
                    }

                    JsonObject result = first.getAsJsonObject();
                    JsonElement titleElement = result.get("title");
                    if (titleElement == null || !titleElement.isJsonPrimitive())
                    {
                        callback.accept(category, null);
                        return;
                    }

                    String title = titleElement.getAsString();
                    if (title.regionMatches(true, 0, CATEGORY_PREFIX, 0, CATEGORY_PREFIX.length()))
                    {
                        callback.accept(title.substring(CATEGORY_PREFIX.length()), null);
                        return;
                    }

                    callback.accept(category, null);
                }
                catch (Throwable t)
                {
                    callback.accept(category, null);
                }
            }
        });
    }

    private static void collectItemIds(JsonElement el, Set<Integer> out)
    {
        if (el == null || !el.isJsonObject())
        {
            return;
        }

        JsonObject obj = el.getAsJsonObject();
        JsonElement idsElement = obj.get("item_id.id");
        if (idsElement == null || idsElement.isJsonNull())
        {
            return;
        }

        if (idsElement.isJsonArray())
        {
            for (JsonElement idElement : idsElement.getAsJsonArray())
            {
                addItemId(idElement, out);
            }
            return;
        }

        addItemId(idsElement, out);
    }

    private static void addItemId(JsonElement el, Set<Integer> out)
    {
        if (el == null || !el.isJsonPrimitive())
        {
            return;
        }

        String s = el.getAsString().trim();
        if (!isDigits(s))
        {
            return;
        }

        try
        {
            int v = Integer.parseInt(s);
            if (v > 0)
            {
                out.add(v);
            }
        }
        catch (NumberFormatException ignored)
        {
        }
    }

    private static boolean isDigits(String s)
    {
        if (s.isEmpty()) return false;
        for (int i = 0; i < s.length(); i++)
        {
            char c = s.charAt(i);
            if (c < '0' || c > '9') return false;
        }
        return true;
    }

    private static String normalizeForBucket(String subject)
    {
        return (subject == null ? "" : subject.replace("_", " ").trim());
    }

    private static List<String> normalizeCategories(List<String> categories)
    {
        if (categories == null || categories.isEmpty())
        {
            return new ArrayList<>();
        }

        LinkedHashSet<String> out = new LinkedHashSet<>();
        for (String category : categories)
        {
            String normalized = normalizeForBucket(category);
            if (!normalized.isEmpty())
            {
                out.add(normalized);
            }
        }
        return new ArrayList<>(out);
    }

    private static String escapeBucketString(String s)
    {
        return s.replace("\\", "\\\\").replace("'", "\\'");
    }

    private static String urlEncode(String s)
    {
        return URLEncoder.encode(s, StandardCharsets.UTF_8);
    }
}

package com.wikitagbankhighlighter;

import com.google.common.base.MoreObjects;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.List;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;
import okhttp3.OkHttpClient;

import static net.runelite.client.plugins.banktags.BankTagsPlugin.CONFIG_GROUP;
import static net.runelite.client.plugins.banktags.BankTagsPlugin.TAG_ICON_PREFIX;
import static net.runelite.client.plugins.banktags.BankTagsPlugin.TAG_TABS_CONFIG;

@Slf4j
@PluginDescriptor(
        name = "Wiki Bank Tools",
        description = "Highlight bank items or create Bank Tag tabs from OSRS Wiki categories."
)
@PluginDependency(BankTagsPlugin.class)
public class WikiBankToolsPlugin extends Plugin
{
    private static final String ICON_PATH = "/wiki_bank_tools_icon.png";

    @Inject private Client client;
    @Inject private ClientThread clientThread;

    @Inject private WikiBankToolsConfig config;
    @Inject private ConfigManager configManager;

    @Inject private OkHttpClient httpClient;

    @Inject private TagManager tagManager;
    @Inject private ItemManager itemManager;

    @Inject private OverlayManager overlayManager;
    @Inject private WikiBankToolsOverlay overlay;

    @Inject private ClientToolbar clientToolbar;

    private NavigationButton navButton;
    private WikiBankToolsPanel panel;

    private volatile int[] highlightIdsSortedDistinct = new int[0];
    private volatile boolean highlightEnabled = false;

    @Provides
    WikiBankToolsConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(WikiBankToolsConfig.class);
    }

    @Override
    protected void startUp()
    {
        overlayManager.add(overlay);

        panel = new WikiBankToolsPanel(this);

        BufferedImage icon = loadIcon(ICON_PATH);
        if (icon == null)
        {
            icon = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
        }

        navButton = NavigationButton.builder()
                .tooltip("Wiki Bank Tools")
                .icon(icon)
                .priority(6)
                .panel(panel)
                .build();

        clientToolbar.addNavigation(navButton);
    }

    @Override
    protected void shutDown()
    {
        highlightEnabled = false;
        highlightIdsSortedDistinct = new int[0];

        if (navButton != null)
        {
            clientToolbar.removeNavigation(navButton);
            navButton = null;
        }

        panel = null;

        overlayManager.remove(overlay);
    }

    public void highlightCategory(String categoryInput)
    {
        final List<String> categories = parseCategoryInput(categoryInput);
        if (categories.isEmpty())
        {
            postChat("Category is empty.");
            return;
        }

        final String label = String.join(", ", categories);
        setPanelBusy(true, "Fetching...");
        postChat("Fetching IDs for categories '" + label + "'...");

        WikiBucketClient.fetchCategoryItemIdsAsync(httpClient, categories, (ids, err) ->
        {
            final int[] sortedDistinct = Arrays.stream(ids).distinct().sorted().toArray();

            clientThread.invokeLater(() ->
            {
                if (err != null)
                {
                    postChat("Fetch failed for '" + label + "': " + err.getMessage());
                    highlightEnabled = false;
                    highlightIdsSortedDistinct = new int[0];
                    return;
                }

                highlightIdsSortedDistinct = sortedDistinct;
                highlightEnabled = true;

                if (sortedDistinct.length == 0)
                {
                    postChat("No items found for '" + label + "'.");
                }
                else
                {
                    postChat("Highlighting " + sortedDistinct.length + " items for '" + label + "'.");
                }
            });

            setPanelBusy(false, "");
        });
    }

    public void createBankTagTab(String categoryInput)
    {
        final List<String> categories = parseCategoryInput(categoryInput);
        if (categories.isEmpty())
        {
            postChat("Category is empty.");
            return;
        }

        final String label = String.join(", ", categories);
        final String tagName = buildCombinedTagName(categories);
        setPanelBusy(true, "Fetching...");
        postChat("Generating Bank Tag Tab for '" + label + "'...");

        WikiBucketClient.fetchCategoryItemIdsAsync(httpClient, categories, (ids, err) ->
        {
            final int[] distinct = Arrays.stream(ids).distinct().toArray();

            clientThread.invokeLater(() ->
            {
                if (err != null)
                {
                    postChat("Fetch failed for '" + label + "': " + err.getMessage());
                    return;
                }

                if (distinct.length == 0)
                {
                    postChat("No items found for '" + label + "'.");
                    return;
                }

                for (int itemId : distinct)
                {
                    tagManager.addTag(itemId, tagName, false);
                }

                createTabIfMissing(tagName, distinct[0]);
                postChat("Added tag/tab '" + tagName + "' to " + distinct.length + " items.");
            });

            setPanelBusy(false, "");
        });
    }

    public void clearHighlight()
    {
        highlightEnabled = false;
        highlightIdsSortedDistinct = new int[0];
        postChat("Highlight cleared.");
    }

    public boolean isHighlightEnabled()
    {
        return highlightEnabled;
    }

    public boolean shouldHighlight(int itemId)
    {
        if (!highlightEnabled || itemId <= 0)
        {
            return false;
        }

        int canonical = itemManager.canonicalize(itemId);
        return Arrays.binarySearch(highlightIdsSortedDistinct, canonical) >= 0;
    }

    private void createTabIfMissing(String tag, int iconItemId)
    {
        List<String> tabs = new ArrayList<>(getAllTabs());

        final String standardized = Text.standardize(tag);
        boolean exists = tabs.stream().map(Text::standardize).anyMatch(t -> t.equals(standardized));

        if (!exists)
        {
            tabs.add(standardized);
            configManager.setConfiguration(CONFIG_GROUP, TAG_TABS_CONFIG, Text.toCSV(tabs));
        }

        configManager.setConfiguration(CONFIG_GROUP, TAG_ICON_PREFIX + standardized, iconItemId);
    }

    private List<String> getAllTabs()
    {
        return Text.fromCSV(MoreObjects.firstNonNull(
                configManager.getConfiguration(CONFIG_GROUP, TAG_TABS_CONFIG),
                ""
        ));
    }

    private void postChat(String msg)
    {
        final String full = "Wiki Bank Tools: " + msg;
        clientThread.invokeLater(() ->
                client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", full, "")
        );
    }

    private void setPanelBusy(boolean busy, String status)
    {
        if (panel == null)
        {
            return;
        }

        javax.swing.SwingUtilities.invokeLater(() -> panel.setBusy(busy, status));
    }

    private static String normalizeCategoryInput(String in)
    {
        if (in == null)
        {
            return "";
        }
        String s = in.trim();
        if (s.regionMatches(true, 0, "Category:", 0, "Category:".length()))
        {
            s = s.substring("Category:".length()).trim();
        }
        return s;
    }

    private static List<String> parseCategoryInput(String input)
    {
        LinkedHashSet<String> categories = new LinkedHashSet<>();
        if (input == null)
        {
            return new ArrayList<>();
        }

        for (String part : input.split(","))
        {
            String normalized = normalizeCategoryInput(part);
            if (!normalized.isEmpty())
            {
                categories.add(normalized);
            }
        }

        return new ArrayList<>(categories);
    }

    private static String buildCombinedTagName(List<String> categories)
    {
        return String.join(", ", categories);
    }

    private static BufferedImage loadIcon(String path)
    {
        try (InputStream in = WikiBankToolsPlugin.class.getResourceAsStream(path))
        {
            if (in == null)
            {
                return null;
            }
            return ImageIO.read(in);
        }
        catch (IOException e)
        {
            return null;
        }
    }
}

package com.wikitagbankhighlighter;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.time.Duration;
import java.time.Instant;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Set;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

@Slf4j
@Singleton
public class WikiCategoryService
{
    private static final String API_BASE = "https://oldschool.runescape.wiki/api.php";

    private final OkHttpClient okHttpClient;

    private Duration defaultTtl = Duration.ofHours(24);

    private final HashMap<Integer, CacheEntry> cache = new HashMap<>();

    @Inject
    public WikiCategoryService(OkHttpClient okHttpClient)
    {
        this.okHttpClient = okHttpClient;
    }

    public void setDefaultTtl(Duration ttl)
    {
        this.defaultTtl = ttl == null ? Duration.ofHours(24) : ttl;
    }

    public void clearCache()
    {
        cache.clear();
    }

    public Set<String> getCategoriesCached(int itemId, Supplier<Set<String>> fetcher)
    {
        CacheEntry e = cache.get(itemId);
        if (e != null && !e.isExpired())
        {
            return e.categories;
        }

        try
        {
            Set<String> cats = fetcher.get();
            if (cats == null)
            {
                cats = Collections.emptySet();
            }
            cache.put(itemId, new CacheEntry(cats, Instant.now().plus(defaultTtl)));
            return cats;
        }
        catch (Exception ex)
        {
            // Don’t spam logs; just cache empty briefly
            log.debug("Wiki category fetch failed for itemId={}", itemId, ex);
            cache.put(itemId, new CacheEntry(Collections.emptySet(), Instant.now().plus(Duration.ofMinutes(30))));
            return Collections.emptySet();
        }
    }

    public Set<String> fetchCategoriesForTitle(String title) throws IOException
    {
        if (title == null || title.trim().isEmpty())
        {
            return Collections.emptySet();
        }

        // MediaWiki action=query&prop=categories&titles=<TITLE>&cllimit=max&format=json&formatversion=2
        HttpUrl url = HttpUrl.parse(API_BASE).newBuilder()
                .addQueryParameter("action", "query")
                .addQueryParameter("prop", "categories")
                .addQueryParameter("titles", title)
                .addQueryParameter("cllimit", "max")
                .addQueryParameter("format", "json")
                .addQueryParameter("formatversion", "2")
                .build();

        Request req = new Request.Builder()
                .url(url)
                .header("User-Agent", "RuneLite Wiki Bank Tag Highlighter (unofficial)")
                .get()
                .build();

        try (Response resp = okHttpClient.newCall(req).execute())
        {
            if (!resp.isSuccessful() || resp.body() == null)
            {
                return Collections.emptySet();
            }

            String body = resp.body().string();
            JsonParser parser = new JsonParser();
            JsonObject root = parser.parse(body).getAsJsonObject();
            JsonObject query = root.has("query") ? root.getAsJsonObject("query") : null;
            if (query == null)
            {
                return Collections.emptySet();
            }

            JsonArray pages = query.has("pages") ? query.getAsJsonArray("pages") : null;
            if (pages == null || pages.size() == 0)
            {
                return Collections.emptySet();
            }

            JsonObject page0 = pages.get(0).getAsJsonObject();
            JsonArray categories = page0.has("categories") ? page0.getAsJsonArray("categories") : null;
            if (categories == null)
            {
                return Collections.emptySet();
            }

            Set<String> out = new HashSet<>();
            for (JsonElement el : categories)
            {
                JsonObject o = el.getAsJsonObject();
                if (o.has("title"))
                {
                    out.add(o.get("title").getAsString()); // e.g. "Category:Herbs"
                }
            }
            return out;
        }
    }

    private static class CacheEntry
    {
        private final Set<String> categories;
        private final Instant expiresAt;

        private CacheEntry(Set<String> categories, Instant expiresAt)
        {
            this.categories = categories;
            this.expiresAt = expiresAt;
        }

        private boolean isExpired()
        {
            return expiresAt != null && Instant.now().isAfter(expiresAt);
        }
    }
}

package com.wikitagbankhighlighter;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.event.ActionEvent;
import javax.swing.*;
import net.runelite.client.ui.PluginPanel;

public class WikiBankToolsPanel extends PluginPanel
{
    private final WikiBankToolsPlugin plugin;

    private final JTextField categoryField = new JTextField();
    private final JButton highlightBtn = new JButton("Highlight in bank");
    private final JButton createTabBtn = new JButton("Create Bank Tag Tab");
    private final JButton clearBtn = new JButton("Clear highlight");
    private final JLabel statusLabel = new JLabel(" ");

    public WikiBankToolsPanel(WikiBankToolsPlugin plugin)
    {
        this.plugin = plugin;

        setLayout(new BorderLayout(0, 8));

        JPanel top = new JPanel();
        top.setLayout(new BoxLayout(top, BoxLayout.Y_AXIS));

        JLabel catLabel = new JLabel("Wiki categories (e.g. Herbs, Potions):");
        catLabel.setAlignmentX(LEFT_ALIGNMENT);

        categoryField.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
        categoryField.setAlignmentX(LEFT_ALIGNMENT);

        JPanel buttons = new JPanel();
        buttons.setLayout(new BoxLayout(buttons, BoxLayout.Y_AXIS));
        buttons.setAlignmentX(LEFT_ALIGNMENT);

        highlightBtn.setAlignmentX(LEFT_ALIGNMENT);
        createTabBtn.setAlignmentX(LEFT_ALIGNMENT);
        clearBtn.setAlignmentX(LEFT_ALIGNMENT);

        highlightBtn.addActionListener(this::onHighlight);
        createTabBtn.addActionListener(this::onCreateTab);
        clearBtn.addActionListener(e -> plugin.clearHighlight());

        buttons.add(highlightBtn);
        buttons.add(Box.createVerticalStrut(6));
        buttons.add(createTabBtn);
        buttons.add(Box.createVerticalStrut(6));
        buttons.add(clearBtn);

        statusLabel.setAlignmentX(LEFT_ALIGNMENT);

        top.add(catLabel);
        top.add(Box.createVerticalStrut(4));
        top.add(categoryField);
        top.add(Box.createVerticalStrut(10));
        top.add(buttons);
        top.add(Box.createVerticalStrut(10));
        top.add(statusLabel);

        add(top, BorderLayout.NORTH);
    }

    private void onHighlight(ActionEvent e)
    {
        plugin.highlightCategory(categoryField.getText());
    }

    private void onCreateTab(ActionEvent e)
    {
        plugin.createBankTagTab(categoryField.getText());
    }

    public void setBusy(boolean busy, String status)
    {
        highlightBtn.setEnabled(!busy);
        createTabBtn.setEnabled(!busy);
        clearBtn.setEnabled(!busy);
        categoryField.setEnabled(!busy);

        statusLabel.setText(status == null || status.isEmpty() ? " " : status);
    }
}

package com.wikitagbankhighlighter;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;

public final class OverlayUtilEx
{
    private OverlayUtilEx() {}

    public static void drawOutline(Graphics2D g, Rectangle r, Color color, int thickness)
    {
        Color old = g.getColor();
        java.awt.Stroke oldStroke = g.getStroke();

        g.setColor(color);
        g.setStroke(new BasicStroke(Math.max(1, thickness)));
        g.drawRect(r.x, r.y, r.width - 1, r.height - 1);

        g.setStroke(oldStroke);
        g.setColor(old);
    }
}

package com.wikitagbankhighlighter;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.ComponentID;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class WikiBankToolsOverlay extends Overlay
{
    @Inject
    private Client client;

    @Inject
    private WikiBankToolsPlugin plugin;

    @Inject
    private WikiBankToolsConfig config;

    @Inject
    public WikiBankToolsOverlay()
    {
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!plugin.isHighlightEnabled())
        {
            return null;
        }

        // Plugin Hub: avoid WidgetInfo/WidgetID, use ComponentID/InterfaceID
        Widget itemContainer = client.getWidget(ComponentID.BANK_ITEM_CONTAINER);
        if (itemContainer == null || itemContainer.isHidden())
        {
            return null; // bank not open
        }

        Widget[] items = itemContainer.getChildren();
        if (items == null)
        {
            return null;
        }

        // Container viewport (on-canvas)
        Point cLoc = itemContainer.getCanvasLocation();
        if (cLoc == null)
        {
            return null;
        }

        int cX = cLoc.getX();
        int cY = cLoc.getY();
        int cW = itemContainer.getWidth();
        int cH = itemContainer.getHeight();
        if (cW <= 0 || cH <= 0)
        {
            return null;
        }

        Rectangle viewport = new Rectangle(cX, cY, cW, cH);

        for (Widget w : items)
        {
            if (w == null || w.isHidden())
            {
                continue;
            }

            int itemId = w.getItemId();
            if (itemId <= 0)
            {
                continue;
            }

            if (!plugin.shouldHighlight(itemId))
            {
                continue;
            }

            Rectangle r = toWidgetBounds(w);
            if (r == null)
            {
                continue;
            }

            // Don't draw outlines for rows that are currently scrolled out of view
            if (!viewport.intersects(r))
            {
                continue;
            }

            OverlayUtilEx.drawOutline(graphics, r, config.outlineColor(), config.outlineThickness());
        }

        return null;
    }

    private Rectangle toWidgetBounds(Widget child)
    {
        Rectangle bounds = child.getBounds();
        if (bounds == null || bounds.width <= 0 || bounds.height <= 0)
        {
            return null;
        }

        return bounds;
    }
}
